INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('excitement','Excitement','minion','Moll',NULL,NULL,'Emotions','{"slug":"excitement","name":"Excitement","team":"minion","ability":"Each night, choose a player: they learn this, are poisoned until dusk & if executed tomorrow their team loses.","creator":"Moll","appearsIn":"Emotions","lede":"Excitement needs a little danger & distraction.","howToRun":["Each night, wake Excitement. They point at any player. Mark the player Excited. Put Excitement to sleep. Wake the player marked Excited. Show them the {{i|This Character Selected You}} info token, then the Excitement token. Put that player to sleep.","The player marked Excited is poisoned. (They wake and act normally. They have no ability, but they think they do. If their ability would give them information, you can give false information to them if you wish. See “Drunkenness and Poisoning” in the rulebook.)","If a player marked Excited is executed, immediately declare that their team has lost.","At dusk, remove the Excited reminder."],"examples":["Aki is the Excitement and Jasper is Guilt. On the first night Aki chooses Jasper. Tonight Jasper wakes to learn that Excitement has chosen them. Jasper chooses Faith & learns ''no'' even though it''s in-play. That day, Jasper is executed & evil wins."],"firstNight":43,"firstNightReminder":"Excitement points to a player. Mark them Excited. Put Excitement to sleep. Wake the player marked Excited. Show the ''This character selected you'' card, then the Excitement token.","otherNight":28,"otherNightReminder":"Excitement points to a player. Mark them Excited. Put Excitement to sleep. Wake the player marked Excited. Show the ''This character selected you'' card, then the Excitement token.","reminders":["Excited"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/w01508gnqg1d6ysel62we2j4.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/i1xeuys7rp0w3rjrkqgo8d5p.png"}','published','emotions/excitement',datetime('now'),datetime('now')),
('gratitude','Gratitude','minion','Moll',NULL,NULL,'Emotions','{"slug":"gratitude","name":"Gratitude","team":"minion","ability":"Once per game, during the day, publicly guess all players characters, if correct, evil wins. [+1 Outsider]","creator":"Moll","appearsIn":"Emotions","lede":"The Gratitude wishes to thank everyone for their valiant efforts.","howToRun":["During the day, the Gratitude can declare that they wish to use their ability. If so, the Gratitude points at each player & a character in any order they wish. If all players are the character the Gratitude pointed to, declare that the Gratitudes team has won. Otherwise, say \"Nothing happens.\" Either way, the Gratitude loses their ability—mark the Gratitude No Ability.","If a player is bluffing as the Gratitude and declares they wish to use their ability, act as if they were indeed the Gratitude—allow time for discussion, let them make the decision, and act like you''re fiddling with tokens in your Grimoire, then say \"Nothing happens.\""],"examples":["Audee is the Gratitude. Aki, Jasper, Swampert & Mint are Love, Grief, Sadness & Boredom respectively. Audee guesses  themselves as Gratitude, Aki as Love, Jasper as Grief, Swampert as Sadness & Mint as Boredom. Evil wins."],"firstNight":0,"otherNight":0,"reminders":["No ability"],"setup":true,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/dnlj4sopot3pxk524uba4qog.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/n7lz72ekjn9qkf24wh51818a.png"}','published','emotions/gratitude',datetime('now'),datetime('now')),
('happiness','Happiness','minion','Moll',NULL,NULL,'Emotions','{"slug":"happiness","name":"Happiness","team":"minion","ability":"You start by choosing a player, they learn this & win if & only if you win.","creator":"Moll","appearsIn":"Emotions","lede":"Happiness speads their happiness.","howToRun":["On the first night, wake Happiness. They point at any player. Mark the player Happy. Put Happiness to sleep. Wake the player marked Happy. Show them the {{i|This Character Selected You}} info token, then the Happiness token. Put that player to sleep.","When the game ends, if Happiness is alive and their team wins, the player marked Happy wins as well. If Happiness team looses, the player marked Happy loses as well."],"examples":["Aki is the Happiness and Jasper is Guilt. On the first night Aki chooses Jasper. Tonight Jasper wakes to learn that Happiness has chosen them. When the game ends only Aki & the demon live so Jasper wins with the evil team."],"firstNight":43,"firstNightReminder":"Happiness points to a player. Mark them Happy. Put Happiness to sleep. Wake the player marked Happy. Show the ''This character selected you'' card, then the Happiness token.","otherNight":0,"reminders":["Happy"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/qhvnva2gnukgd61gfm4lxoqc.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/p833tmxpw7tnz18goenz5hsg.png"}','published','emotions/happiness',datetime('now'),datetime('now')),
('love','Love','demon','Moll',NULL,NULL,'Emotions','{"slug":"love","name":"Love","team":"demon","ability":"Each night, choose a player: they die tomorrow night. If they''re a Minion, you learn their character.","creator":"Moll","appearsIn":"Emotions","lede":"Show your Love, it burns so strong!!","howToRun":["Each night, the player marked Dies Tomorrow, dies --- mark them with the Dead reminder, remove their Dies Tomorrow reminder. Wake Love. They point at any player. Mark that player Dies Tomorrow. If they''re a Minion, show their character token. Put Love to sleep."],"examples":["Harry is Love and Audee is Excietement. On the first night Harry chooses Audee and learns Excitement, the next night Audee dies."],"firstNight":47,"firstNightReminder":"Love points to a player. Mark them Dies Tomorrow If they''re a Minion, show Love their character token.","otherNight":42,"otherNightReminder":"The player marked Dies Tomorrow dies. Love points to a player. Mark them Dies Tomorrow If they''re a Minion, show Love their character token.","reminders":["Dies tomorrow","Dead"],"setup":false,"image":"https://user-images.klutzbanana.com/c4lf26ztn97jgf23nhec1a1p.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/nk1oslkxhhhs1201554j33bj.png"}','published','emotions/love',datetime('now'),datetime('now')),
('hope','Hope','demon','Moll',NULL,NULL,'Emotions','{"slug":"hope","name":"Hope","team":"demon","ability":"Each night, you see the grimoire. Each night*, choose a player: they die. You''re safe from Minions & they''re secretly good. [-? Outsiders. +1 Minion]","creator":"Moll","appearsIn":"Emotions","lede":"Hope is the feeling of believing everything will be alright, can you hold hope against all odds?","howToRun":["When putting character tokens into the bag, remove a Townsfolk and add a Minion instead. You may remove any number of Outsiders, add a Townsfolk token for each.","While preparing the first night, change all minions alignment to Good, do not tell them this. When the game ends, announce that they win or lose with good.","Each night, wake Hope. Show them the Grimoire for as long as they need. Put Hope to sleep.","Each night except the first, wake Hope. They point at any player. That player dies - mark them with the Dead reminder. Put Hope to sleep.","If a Minion would do anything harmful to Hope such as poisoning them or changing their alignment, they do not."],"examples":["During setup Happiness, Gratitude, Boredom, Guilt and Hope was given out. At the end of the game when Hope is executed good wins, including Gratitude and Happiness."],"firstNight":47,"firstNightReminder":"Show Hope the grimoire.","otherNight":42,"otherNightReminder":"Show Hope the grimoire. They point to a player, who dies.","reminders":["Dead"],"setup":true,"special":[{"type":"signal","name":"grimoire","time":"night"}],"image":"https://user-images.klutzbanana.com/h8gndc4r5dwdo3wrt5yl68xy.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/z2p0tb4w4vvsybsxsjznelwt.png"}','published','emotions/hope',datetime('now'),datetime('now')),
('faith','Faith','demon','Moll',NULL,NULL,'Emotions','{"slug":"faith","name":"Faith","team":"demon","ability":"Each night*, a player might die. If only 3 live & you die, good wins. Faith think they''re the same character. [Minions are Faith]","creator":"Moll","appearsIn":"Emotions","lede":"Faith is all you need, are you faithful?","howToRun":["While setting up the game, before putting character tokens in the bag, remove the Faith token and all Minion character tokens. Add that many copies of the same token to the bag. Players who draw that token is Faith, mark them with the Is Faith reminder.","During the game, act as if Faith is actually the character they saw. (If that character would wake to act at night, Faith wakes to act. If their ability would give them information, you can give false information to them if you wish.)","Each night, except the first, you may kill a player, mark them Dead."],"examples":["When the bag is made, Faith & Minion tokens are replaced with 2 Fear tokens. When the tokens are passed out Nicklas and Lucifer draws one each."],"firstNight":0,"otherNight":42,"otherNightReminder":"You may choose a player, they die.","remindersGlobal":["Is Faith","Is Faith","Is Faith","Is Faith","Dead","Dead"],"setup":true,"special":[{"type":"selection","name":"bag-disabled"},{"type":"reveal","name":"replace-character"}],"image":"https://user-images.klutzbanana.com/vchbjsuuiss073y8v3n0q4ob.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/qm4obg3lxxbilbjwbrtu23cx.png","tips":["When running irl, it would be best to hand out tokens by showing them to players 1 at a time instead of by using the bag. This means you can still hand out duplicates for Faith or Dissapointment."]}','published','emotions/faith',datetime('now'),datetime('now')),
('depression','Depression','traveller','Moll',NULL,NULL,'Emotions','{"slug":"depression","name":"Depression","team":"traveller","ability":"Each night*, choose a player (not yourself): they learn your alignment. If you are exiled, change alignments.","creator":"Moll","appearsIn":"Emotions","lede":"Depression tries to tell others how they feel.","howToRun":["Each night, wake Depression. They point at any player other than themselves. Put Depression to sleep. Wake this player, show them the \"This Character Selected You\" info token, then the Depression token & give a hand signal for Depressions alignment.","If Depression is exiled. If they''re good, they become evil & vice versa. Turn their character token upside down to show their new alignment."],"examples":["Swampert is the Evil Depression. On the first night Swampert does not learn who the Demon is, and the next day noone is executed. That night Swampert chooses Lucifer who learns that Swampert is evil. The next day Swampert is exiled & becomes good, but is not told."],"firstNight":0,"otherNight":2,"otherNightReminder":"Depression points to a player. Put Depression to sleep. Wake the chosen player, how the ''This character selected you'' card, then the Depression token, and a hand signal for Depressions alignment.","setup":false,"image":"https://user-images.klutzbanana.com/qto1tz913asop8fmu5xu6fzg.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/df0fjnn6j27jttbssjfhbgvo.png","imageAlt2":"https://user-images.klutzbanana.com/lx4g0r3o7x2ll4oh8j8huf60.png"}','published','emotions/depression',datetime('now'),datetime('now')),
('the-spiral','The spiral','fabled','Moll',NULL,NULL,'Emotions','{"slug":"the-spiral","name":"The spiral","team":"fabled","ability":"Travelers don''t know the Demon or their alignment & can only die by exile.","creator":"Moll","appearsIn":"Emotions","lede":"The Spiral keeps Travellers safe & confused.","howToRun":["When a Traveller travels in, do not tell them their alignment. If they''re evil, do not tell who the Demon is.","If a Traveller would die by anything but exile, do not mark them dead."],"examples":["On the 2nd night, Hope chooses Depression. Depression doesn''t die.","On the 2nd night, an evil Depression travels in but does not learn they''re evil nor who the Demon is."],"firstNight":0,"otherNight":0,"setup":false,"image":"https://user-images.klutzbanana.com/szxfsl42upieygw924sjagjh.png","curata":false}','published','emotions/the-spiral',datetime('now'),datetime('now'));
